macro_rules! deps {
    () => {
        MaxScored!();
        Graph!();
        Undirected!();
        Time!();
    };
}

macro_rules! dsatur_coloring {
    () => {
        deps!();
        # [doc = " [DStatur algorithm][1] to properly color a non weighted undirected graph."] # [doc = ""] # [doc = ""] # [doc = " This is a heuristic. So, it does not necessarily return a minimum coloring."] # [doc = " The graph must be undirected. It should not contain loops."] # [doc = ""] # [doc = " # Arguments"] # [doc = " * `graph`: undirected graph without loops."] # [doc = ""] # [doc = " # Returns"] # [doc = " Returns a tuple of:"] # [doc = " * [`struct@hashbrown::HashMap`] that associates to each `NodeId` its color."] # [doc = " * `usize`: the number of used colors."] # [doc = ""] # [doc = " # Complexity"] # [doc = " * Time complexity: **O((|V| + |E|)log(|V|)**."] # [doc = " * Auxiliary space: **O(|V| + |E|)**."] # [doc = ""] # [doc = " where **|V|** is the number of nodes and **|E|** is the number of edges."] # [doc = ""] # [doc = " [1]: https://en.wikipedia.org/wiki/DSatur"] # [doc = ""] # [doc = " # Example"] # [doc = " ```rust"] # [doc = " use petgraph::{Graph, Undirected};"] # [doc = " use petgraph::algo::dsatur_coloring;"] # [doc = ""] # [doc = " let mut graph: Graph<(), (), Undirected> = Graph::new_undirected();"] # [doc = " let a = graph.add_node(());"] # [doc = " let b = graph.add_node(());"] # [doc = " let c = graph.add_node(());"] # [doc = " let d = graph.add_node(());"] # [doc = " let e = graph.add_node(());"] # [doc = " let f = graph.add_node(());"] # [doc = ""] # [doc = " graph.extend_with_edges(&["] # [doc = "     (a, b),"] # [doc = "     (b, c),"] # [doc = "     (c, d),"] # [doc = "     (d, e),"] # [doc = "     (e, f),"] # [doc = "     (f, a),"] # [doc = " ]);"] # [doc = ""] # [doc = " // a ----- b ----- c"] # [doc = " // |               |"] # [doc = " // |               |"] # [doc = " // |               |"] # [doc = " // f ----- e------ d"] # [doc = ""] # [doc = " let (coloring, nb_colors) = dsatur_coloring(&graph);"] # [doc = " assert_eq!(nb_colors, 2);"] # [doc = " assert_ne!(coloring[&a], coloring[&b]);"] # [doc = " ```"] pub fn dsatur_coloring < G > (graph : G) -> (HashMap < G :: NodeId , usize > , usize) where G : IntoEdges + IntoNodeIdentifiers + Visitable + NodeIndexable , G :: NodeId : Eq + Hash , { let ix = | v | graph . to_index (v) ; let n = graph . node_bound () ; let mut degree_map = vec ! [0 ; n] ; let mut queue = BinaryHeap :: with_capacity (n) ; let mut colored = HashMap :: with_capacity (n) ; let mut adj_color_map = vec ! [HashSet :: new () ; n] ; let mut seen = graph . visit_map () ; let mut max_color = 0 ; for node in graph . node_identifiers () { let degree = graph . edges (node) . count () ; queue . push (MaxScored ((0 , degree) , node)) ; degree_map [ix (node)] = degree ; } while let Some (MaxScored (_ , node)) = queue . pop () { if seen . is_visited (& node) { continue ; } seen . visit (node) ; let adj_color = & adj_color_map [ix (node)] ; let mut color = 0 ; while adj_color . contains (& color) { color += 1 ; } colored . insert (node , color) ; max_color = max_color . max (color) ; for nbor in graph . neighbors (node) { if let Some (adj_color) = adj_color_map . get_mut (ix (nbor)) { adj_color . insert (color) ; queue . push (MaxScored ((adj_color . len () , degree_map [ix (nbor)]) , nbor)) ; } } } (colored , max_color + 1) }
    };
}

dsatur_coloring!()